const payload = $json.body ?? $json;
const text = JSON.stringify(payload).toLowerCase();
const urgentTerms = ['leak', 'water', 'missing shingles', 'hail', 'wind', 'storm', 'tarp'];
const urgencyScore = urgentTerms.filter((term) => text.includes(term)).length + (payload.activeLeak ? 3 : 0) + (payload.photosAvailable ? 1 : 0);
const priority = urgencyScore >= 4 ? 'inspection-needed' : urgencyScore >= 2 ? 'same-day-callback' : 'normal-follow-up';
return [{ json: { leadId: `DEMO-ROOF-${Date.now()}`, priority, urgencyScore, nextAction: priority === 'inspection-needed' ? 'Route to inspection scheduler.' : 'Create office callback task.', lead: payload } }];
